semio-framework-value = { path = "../../🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-framework-ui-contract = { path = "../../🔨️modules/🖱️ui/🧬️contract/📦️packages/🦀️rust", package = "semio-framework-ui-contract" }
semio-framework-actor = { workspace = true }
semio-framework-job = { path = "../../🔨️modules/🧵️job/📦️packages/🦀️rust", package = "semio-framework-job" }
# ⏯️ `ToolRunDefinition` on `ToolDefinition`/`UtilityDefinition` and the reserved tool run actions (manifest region `🔖️ToolRun`).
semio-framework-tool-run = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
ui_wgpu = { path = "../../🔨️modules/🖱️ui/📦️packages/🦀️rust", package = "semio-framework-ui", features = ["wgpu"] }
