semio-framework-value-derive = { path = "../../🔨️modules/🌱️value/✨️derive/📦️packages/🦀️rust", package = "semio-framework-value-derive" }
# 🧬️ `register_scope_schema_exports`/`resolve_schema_export` — the `(scope id, export id, format id)`
# registry this crate's mounted `interaction::schema` leaf declares its named exports into.
semio-framework-schema = { workspace = true }

[dev-dependencies]
semio-framework-async-macros = { path = "../../🔨️modules/⏳️async/✨️macros/📦️packages/🦀️rust" }
# 🔬️ Third-party oracle for `kernel::media_export_bytes`'s base64 lane — dev-only, never a runtime dep.
base64 = "0.22.1"

[features]
# 🧬️ Generates the TypeScript mirror for boundary/protocol types (see `<owner>/🤖️generated/🪪️manifest/🟦️.ts`);
# never enabled by default so schema projection never affects the plain build/test path.
typegen = []

